import React, { useEffect, useState } from "react"
import PortalLayout from "../../components/portal/PortalLayout"
import AppointmentCard, {
  PortalAppointment,
  PortalVehicle,
} from "../../components/portal/AppointmentCard"

interface PortalData {
  clientName: string
  clientEmail: string
  vehicles: PortalVehicle[]
  upcoming: PortalAppointment[]
  past: PortalAppointment[]
}

type State =
  | { status: "loading" }
  | { status: "invalid"; reason: "not-found" | "expired" | "error" }
  | { status: "valid"; data: PortalData }

const SHOP_NAME = "Garage Carlos Inc."
const SHOP_PHONE = ""
const SHOP_EMAIL = ""

export default function PortalPage({ params }: { params: { token: string } }) {
  const [state, setState] = useState<State>({ status: "loading" })

  useEffect(() => {
    if (!params?.token) {
      setState({ status: "invalid", reason: "not-found" })
      return
    }

    const apiBase = (process.env.GATSBY_API_URL ?? "").replace(/\/$/, "")
    fetch(`${apiBase}/api/validate-portal-token?token=${encodeURIComponent(params.token)}`)
      .then(res => res.json())
      .then(data => {
        if (data.valid) {
          setState({
            status: "valid",
            data: {
              clientName: data.clientName,
              clientEmail: data.clientEmail,
              vehicles: data.vehicles ?? [],
              upcoming: data.upcoming ?? [],
              past: data.past ?? [],
            },
          })
        } else {
          setState({
            status: "invalid",
            reason: data.reason === "expired" ? "expired" : "not-found",
          })
        }
      })
      .catch(() => setState({ status: "invalid", reason: "error" }))
  }, [params?.token])

  if (state.status === "loading") {
    return (
      <PortalLayout shopName={SHOP_NAME} shopPhone={SHOP_PHONE} shopEmail={SHOP_EMAIL}>
        <div className="flex flex-col items-center justify-center py-24 gap-4 text-gray-400">
          <div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
          <p className="text-sm">Loading your appointments…</p>
        </div>
      </PortalLayout>
    )
  }

  if (state.status === "invalid") {
    const message =
      state.reason === "expired"
        ? "This link has expired. Please contact us for a new one."
        : "This link is not valid."

    return (
      <PortalLayout shopName={SHOP_NAME} shopPhone={SHOP_PHONE} shopEmail={SHOP_EMAIL}>
        <div className="flex flex-col items-center justify-center py-24 gap-4 text-center">
          <span className="text-5xl">🔒</span>
          <p className="text-gray-700 font-medium">{message}</p>
          {SHOP_PHONE && (
            <p className="text-sm text-gray-500">
              Call us at <a href={`tel:${SHOP_PHONE}`} className="text-blue-600 hover:underline">{SHOP_PHONE}</a>
            </p>
          )}
        </div>
      </PortalLayout>
    )
  }

  const { data } = state

  return (
    <PortalLayout shopName={SHOP_NAME} shopPhone={SHOP_PHONE} shopEmail={SHOP_EMAIL}>
      {/* Greeting */}
      <div className="mb-6">
        <h1 className="text-xl font-bold text-gray-800">Hi, {data.clientName.split(" ")[0]}!</h1>
        <p className="text-sm text-gray-500 mt-0.5">Here are your upcoming appointments.</p>
      </div>

      {/* Upcoming */}
      <section className="mb-8">
        {data.upcoming.length === 0 ? (
          <div className="bg-white rounded-xl border border-gray-200 p-6 text-center text-gray-400 space-y-2">
            <p className="text-sm">No upcoming appointments.</p>
            <p className="text-sm">Contact us to schedule one.</p>
            {SHOP_PHONE && (
              <p className="text-sm text-blue-600">
                <a href={`tel:${SHOP_PHONE}`} className="hover:underline">{SHOP_PHONE}</a>
              </p>
            )}
            {SHOP_EMAIL && (
              <p className="text-sm text-blue-600">
                <a href={`mailto:${SHOP_EMAIL}`} className="hover:underline">{SHOP_EMAIL}</a>
              </p>
            )}
          </div>
        ) : (
          <div className="space-y-3">
            {data.upcoming.map(appt => (
              <AppointmentCard key={appt.id} appointment={appt} vehicles={data.vehicles} />
            ))}
          </div>
        )}
      </section>

      {/* Past appointments */}
      {data.past.length > 0 && (
        <section>
          <h2 className="text-sm font-semibold text-gray-500 uppercase tracking-wide mb-3">
            Past Appointments
          </h2>
          <div className="space-y-3">
            {data.past.map(appt => (
              <AppointmentCard key={appt.id} appointment={appt} vehicles={data.vehicles} />
            ))}
          </div>
        </section>
      )}
    </PortalLayout>
  )
}
