import React from "react"
import { format, parseISO } from "date-fns"

// Status colors match the admin panel (STATUS_COLORS from CalendarGrid)
const STATUS_COLORS: Record<string, string> = {
  scheduled: "bg-blue-100 text-blue-700",
  confirmed: "bg-green-100 text-green-700",
  "pending-approval": "bg-yellow-100 text-yellow-700",
  "in-progress": "bg-purple-100 text-purple-700",
  completed: "bg-gray-100 text-gray-600",
  cancelled: "bg-red-100 text-red-600",
}

const STATUS_LABELS: Record<string, string> = {
  scheduled: "Scheduled",
  confirmed: "Confirmed",
  "pending-approval": "Pending Approval",
  "in-progress": "In Progress",
  completed: "Completed",
  cancelled: "Cancelled",
}

export interface PortalAppointment {
  id: string
  date: string | null
  timeSlot: string
  status: string
  serviceType: string
  notes: string
  estimatedDuration: number | null
  vehicleId: string | null
}

export interface PortalVehicle {
  vehicleId: string
  make: string
  model: string
  year: number
  color: string
}

interface AppointmentCardProps {
  appointment: PortalAppointment
  vehicles: PortalVehicle[]
}

export default function AppointmentCard({ appointment, vehicles }: AppointmentCardProps) {
  const vehicle = vehicles.find(v => v.vehicleId === appointment.vehicleId)

  const dateLabel = appointment.date
    ? format(parseISO(appointment.date), "EEEE, MMMM d, yyyy")
    : "Date TBD"

  const serviceLabel =
    appointment.serviceType === "custom"
      ? appointment.notes || "Custom Service"
      : appointment.serviceType.replace(/-/g, " ").replace(/\b\w/g, c => c.toUpperCase())

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-4 space-y-3">
      <div className="flex items-start justify-between gap-3">
        <div>
          <p className="text-sm font-semibold text-gray-800">
            📅 {dateLabel}
          </p>
          {appointment.timeSlot && (
            <p className="text-xs text-gray-500 mt-0.5">at {appointment.timeSlot}</p>
          )}
        </div>
        <span
          className={`text-xs px-2 py-0.5 rounded-full font-medium flex-shrink-0 ${
            STATUS_COLORS[appointment.status] ?? "bg-gray-100 text-gray-600"
          }`}
        >
          {STATUS_LABELS[appointment.status] ?? appointment.status}
        </span>
      </div>

      <div className="space-y-1.5 text-sm text-gray-700">
        {vehicle && (
          <p>
            🚗{" "}
            <span className="font-medium">
              {vehicle.year} {vehicle.make} {vehicle.model}
            </span>
            {vehicle.color ? ` — ${vehicle.color}` : ""}
          </p>
        )}
        <p>🔧 <span className="capitalize">{serviceLabel}</span></p>
        {appointment.estimatedDuration && (
          <p className="text-xs text-gray-400">
            Est. duration: {appointment.estimatedDuration} min
          </p>
        )}
      </div>
    </div>
  )
}
